import memfs from 'memfs'
import { NowConfig, type FileSystem, GUID, type Logger, type Telemetry } from '@servicenow/sdk-build-core'
import { type IConnector, Orchestrator, Project } from '../../src'
import { MockConnector } from './mock-connector'
import { createZip } from './utils'

describe('Orchestrator.install Test Suite', () => {
    const logger: Logger = {
        info: jest.fn(),
        warn: jest.fn(),
        error: jest.fn(),
        debug: jest.fn(),
    }
    const scopeId = GUID()

    let orchestrator: Orchestrator
    let connector: IConnector
    let project: Project
    let zipPath: string
    let telemetry: Telemetry

    beforeEach(async () => {
        jest.clearAllMocks()

        const vol = new memfs.Volume()
        const fs = memfs.createFsFromVolume(vol)
        telemetry = {
            sendEvent: jest.fn(),
            error: jest.fn(),
            startTimerEvent: jest.fn().mockReturnValue({
                end: jest.fn().mockReturnValue({ name: 'install', data: {} }),
            }),
        } as unknown as Telemetry
        project = new Project({
            fileSystem: fs as FileSystem,
            logger,
            rootDir: '/',
            config: NowConfig.parse({ scope: 'x_test', scopeId }, logger),
            telemetryClient: telemetry,
        })

        zipPath = await createZip(fs as FileSystem, vol, ['businessrule.xml', 'sys_ui_form.xml'])
    })

    test('Throws error when package zip path is invalid', async () => {
        const options = {
            clean: false,
            packageZipPath: 'invalidpath.zip',
            installAsStoreApp: false,
        }

        connector = new MockConnector({
            appUpgradeStatus: async () => {
                return { finished: true, id: GUID() }
            },
            getScopeInfo: async (_, scopeId) => {
                return {
                    sysClassName: 'sys_app',
                    appId: scopeId,
                    active: true,
                    name: scopeId,
                    scope: 'scope',
                    shortDescription: '',
                }
            },
        })

        orchestrator = new Orchestrator(project, connector)

        await expect(orchestrator.install(options)).rejects.toThrow(
            "Installation failed due to missing installation artifact 'invalidpath.zip'. Run $now-sdk build before running $now-sdk install to generate a build artifact for installation."
        )

        expect(telemetry.error).toHaveBeenCalledWith('install', expect.any(Error))
        expect(telemetry.sendEvent).not.toHaveBeenCalled()
        expect(((telemetry.error as jest.Mock).mock.calls[0]?.[1] as Error | undefined)?.message).toBe(
            "Installation failed due to missing installation artifact 'invalidpath.zip'. Run $now-sdk build before running $now-sdk install to generate a build artifact for installation."
        )
    })

    test('Throws error when trying to install a store app but a corresponding sys_app record is present', async () => {
        const options = {
            clean: false,
            packageZipPath: 'invalidpath.zip',
            installAsStoreApp: true,
        }

        connector = new MockConnector({
            appUpgradeStatus: async () => {
                return { finished: true, id: GUID() }
            },
            getScopeInfo: async (_, scopeId) => {
                return {
                    sysClassName: 'sys_app',
                    appId: scopeId,
                    active: true,
                    name: scopeId,
                    scope: 'scope',
                    shortDescription: '',
                }
            },
        })

        orchestrator = new Orchestrator(project, connector)

        await expect(orchestrator.install(options)).rejects.toThrow(
            "Attempting to install a store app record but there is already a sys_app record for this scope present on the instance. Install with flag '--reinstall' (-r) to delete existing app and reinstall"
        )

        expect(telemetry.error).toHaveBeenCalledWith('install', expect.any(Error))
        expect(telemetry.sendEvent).not.toHaveBeenCalled()
    })

    test('Throws error if the execution tracker returns error status', async () => {
        const options = {
            clean: false,
            packageZipPath: zipPath,
            installAsStoreApp: false,
        }

        connector = new MockConnector({
            appUpgradeStatus: async () => {
                return { finished: true, id: GUID() }
            },
            getScopeInfo: async (_, scopeId) => {
                return {
                    sysClassName: 'sys_app',
                    appId: scopeId,
                    active: true,
                    name: scopeId,
                    scope: 'scope',
                    shortDescription: '',
                }
            },
            uploadScopedAppPackage: async () => {
                return { trackerId: GUID(), rollbackId: GUID() }
            },
            getProgress: async () => {
                return {
                    status: '3',
                    percent_complete: 100,
                    status_message: 'Missing required plugins.',
                }
            },
        })

        orchestrator = new Orchestrator(project, connector)

        await expect(orchestrator.install(options)).rejects.toThrow('Missing required plugins.')

        expect(telemetry.error).toHaveBeenCalledWith('install', expect.any(Error))
        expect(telemetry.sendEvent).not.toHaveBeenCalled()
    })

    test('Logs if unable to determine the installation status', async () => {
        const options = {
            clean: false,
            packageZipPath: zipPath,
            installAsStoreApp: false,
        }

        connector = new MockConnector({
            appUpgradeStatus: async () => {
                return { finished: true, id: '1234' }
            },
            getScopeInfo: async (scope, scopeId) => {
                return {
                    sysClassName: 'sys_app',
                    appId: scopeId,
                    active: true,
                    name: scope,
                    scope: scope,
                    shortDescription: '',
                }
            },
            uploadScopedAppPackage: async () => {
                return undefined
            },
            getProgress: async () => {
                return { status: '2', percent_complete: 100, status_message: '' }
            },
        })

        orchestrator = new Orchestrator(project, connector)
        await expect(orchestrator.install(options)).rejects.toThrow(
            'Could not determine app installation status. Check instance to verify installation.'
        )

        expect(telemetry.error).toHaveBeenCalledWith('install', expect.any(Error))
        expect(telemetry.sendEvent).not.toHaveBeenCalled()
    })

    test('Installs the app successfully', async () => {
        const options = {
            clean: false,
            packageZipPath: zipPath,
            installAsStoreApp: false,
        }

        connector = new MockConnector({
            appUpgradeStatus: async () => {
                return { finished: true, id: GUID() }
            },
            getScopeInfo: async (_, scopeId) => {
                return {
                    sysClassName: 'sys_app',
                    appId: scopeId,
                    active: true,
                    name: scopeId,
                    scope: 'scope',
                    shortDescription: '',
                }
            },
            uploadScopedAppPackage: async () => {
                return { trackerId: GUID(), rollbackId: '1234' }
            },
            getProgress: async () => {
                return { status: '2', percent_complete: 100, status_message: '' }
            },
        })

        orchestrator = new Orchestrator(project, connector)
        await orchestrator.install(options)

        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()

        expect(logger.info).toHaveBeenCalledWith(
            'Rollback (undo installation): https://example.com/sys_rollback_context.do?sys_id=1234'
        )
    })

    test('Falls back to legacy install check if execution tracker id is not present', async () => {
        const options = {
            clean: false,
            packageZipPath: zipPath,
            installAsStoreApp: false,
        }

        let latestUpgradeId = '1234'
        const computeAndUpdateUpgradeId = () => {
            latestUpgradeId = GUID()
            return latestUpgradeId
        }
        connector = new MockConnector({
            appUpgradeStatus: async () => {
                return { finished: true, id: computeAndUpdateUpgradeId() }
            },
            getScopeInfo: async (_, scopeId) => {
                return {
                    sysClassName: 'sys_app',
                    appId: scopeId,
                    active: true,
                    name: scopeId,
                    scope: 'scope',
                    shortDescription: '',
                }
            },
            uploadScopedAppPackage: async () => {
                return undefined
            },
            getProgress: async () => {
                return { status: '2', percent_complete: 100, status_message: '' }
            },
        })

        orchestrator = new Orchestrator(project, connector)
        await expect(orchestrator.install(options)).resolves.not.toThrow()

        expect(telemetry.sendEvent).toHaveBeenCalled()
        expect(telemetry.error).not.toHaveBeenCalled()
    })

    test('Can disable or enable the demodata flag on install', async () => {
        const options = {
            clean: false,
            packageZipPath: zipPath,
            installAsStoreApp: false,
            demoData: false,
        }

        const uploadScopedAppPackage = jest.fn(async () => {
            return { trackerId: GUID(), rollbackId: '1234' }
        })

        connector = new MockConnector({
            appUpgradeStatus: async () => {
                return { finished: true, id: GUID() }
            },
            getScopeInfo: async (_, scopeId) => {
                return {
                    sysClassName: 'sys_app',
                    appId: scopeId,
                    active: true,
                    name: scopeId,
                    scope: 'scope',
                    shortDescription: '',
                }
            },
            uploadScopedAppPackage,
            getProgress: async () => {
                return { status: '2', percent_complete: 100, status_message: '' }
            },
        })

        orchestrator = new Orchestrator(project, connector)
        await orchestrator.install(options)

        expect(logger.info).toHaveBeenCalledWith(
            'Rollback (undo installation): https://example.com/sys_rollback_context.do?sys_id=1234'
        )

        expect(uploadScopedAppPackage).toHaveBeenCalledWith(
            expect.any(Blob),
            expect.objectContaining({
                loadDemoData: false,
            })
        )

        options.demoData = true
        await orchestrator.install(options)

        expect(uploadScopedAppPackage).toHaveBeenCalledWith(
            expect.any(Blob),
            expect.objectContaining({
                loadDemoData: true,
            })
        )
    })
})
